{"version":"v0.9","updateComponents":{"surfaceId":"feedback","components":[{"id":"root","component":"Box","style":{"display":"flex","justifyContent":"center","padding":"$spacing.lg"},"children":["card","toast"]},{"id":"card","component":"Card","title":"Send us feedback","description":"Tell us what's working, what's broken, or what you'd love to see next.","style":{"width":"100%","maxWidth":"560px"},"children":["form"]},{"id":"form","component":"Form","name":"feedback","children":["ratingGroup","category","message","screenshot","actions"],"on":{"submit":{"event":{"name":"feedback.submit","context":{"rating":{"path":"/feedback/rating"},"category":{"path":"/feedback/category"},"message":{"path":"/feedback/message"},"screenshots":{"path":"/feedback/files"}}},"functionCall":{"call":"set","args":{"path":"/toastOpen","value":true}}}}},{"id":"ratingGroup","component":"Stack","gap":"xs","children":["ratingLabel","ratingRow"]},{"id":"ratingLabel","component":"Label","text":"How would you rate your experience?","required":true},{"id":"ratingRow","component":"Stack","direction":"horizontal","gap":"sm","align":"center","children":["rating","ratingText"]},{"id":"rating","component":"Rating","max":5,"size":"lg","value":{"path":"/feedback/rating"}},{"id":"ratingText","component":"Text","variant":"muted","text":{"call":"map","args":{"value":{"path":"/feedback/rating"},"cases":{"1":"Poor","2":"Fair","3":"Good","4":"Great","5":"Excellent"},"default":"Not rated yet"}}},{"id":"category","component":"ChoiceTiles","name":"category","columns":3,"value":{"path":"/feedback/category"},"options":[{"label":"Bug","value":"bug","icon":"bug","description":"Something isn't working"},{"label":"Idea","value":"idea","icon":"lightbulb","description":"A suggestion or request"},{"label":"Praise","value":"praise","icon":"heart","description":"Something you love"}],"checks":[{"condition":{"call":"required","args":{"value":{"path":"/feedback/category"}}},"message":"Pick a category."}]},{"id":"message","component":"Textarea","name":"message","label":"Message","placeholder":"Describe what happened or what you have in mind…","rows":5,"autosize":true,"maxRows":12,"value":{"path":"/feedback/message"},"checks":[{"condition":{"call":"required","args":{"value":{"path":"/feedback/message"}}},"message":"Please write a message."},{"condition":{"call":"length","args":{"value":{"path":"/feedback/message"},"min":10,"max":2000}},"message":"Use between 10 and 2000 characters."}]},{"id":"screenshot","component":"FileUpload","name":"screenshot","label":"Screenshot (optional)","accept":"image/*","multiple":true,"maxSize":10485760,"hint":"PNG or JPG, up to 10 MB each","files":{"path":"/feedback/files"}},{"id":"actions","component":"Stack","direction":"horizontal","justify":"end","align":"center","gap":"sm","children":["ratingHint","submit"]},{"id":"ratingHint","component":"Text","variant":"caption","tone":"warning","text":"Add a star rating to send.","visible":{"call":"eq","args":{"a":{"path":"/feedback/rating"},"b":0}}},{"id":"submit","component":"Button","label":"Send feedback","icon":"send","submit":true,"pendingLabel":"Sending…","disabled":{"call":"eq","args":{"a":{"path":"/feedback/rating"},"b":0}}},{"id":"toast","component":"Toast","type":"success","title":"Thanks for your feedback!","description":"We read every message and it helps us improve.","duration":5000,"open":{"path":"/toastOpen"}}]}}
